       margin: 0 0 16px;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .option-list {
       display: grid;
       gap: 12px;
       margin: 0;
       padding: 0;
       list-style: none;
     }

     .option {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border-radius: 14px;
       border: 1px solid rgba(148, 163, 184, 0.16);
       background: rgba(2, 6, 23, 0.38);
       transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
       cursor: pointer;
     }

     .option:hover {
       border-color: rgba(139, 92, 246, 0.45);
       background: rgba(30, 41, 59, 0.56);
       transform: translateY(-1px);
     }

     .option input {
       width: 18px;
       height: 18px;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     .option span {
       color: var(--text);
     }

     .actions {
       display: flex;
       gap: 14px;
       align-items: center;
       margin-top: 22px;
       flex-wrap: wrap;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 14px 22px;
       font-weight: 700;
       color: white;
       background: linear-gradient(135deg, var(--accent), #2563eb);
       box-shadow: 0 14px 34px rgba(91, 33, 182, 0.28);
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.05);
     }

     .result {
       color: var(--muted);
       font-size: 0.95rem;
     }

     @media (max-width: 640px) {
       .quiz-header,
       form {
         padding-left: 18px;
         padding-right: 18px;
       }

       .form-field {
         padding: 18px;
       }
     }
   </style>
 </head>
 <body>
   <main class="quiz-card">
     <header class="quiz-header">
       <h1>Computer Languages Quiz</h1>
       <p>Select all answers that apply for each question, then submit to see your score.</p>
     </header>

     <form id="quizForm">
       <div class="form-field">
         <div class="question-title">1. Which of these are programming languages?</div>
         <p class="help-text">Choose every correct option. More than one answer may be right.</p>
         <div class="option-list">
           <label class="option"><input type="checkbox" name="q1" value="python" /><span>Python</span></label>
           <label class="option"><input type="checkbox" name="q1" value="html" /><span>HTML</span></label>
           <label class="option"><input type="checkbox" name="q1" value="javascript" /><span>JavaScript</span></label>
           <label class="option"><input type="checkbox" name="q1" value="css" /><span>CSS</span></label>
         </div>
       </div>

       <div class="form-field">
         <div class="question-title">2. Which languages are commonly used for web development?</div>
         <div class="option-list">
           <label class="option"><input type="checkbox" name="q2" value="javascript" /><span>JavaScript</span></label>
           <label class="option"><input type="checkbox" name="q2" value="ruby" /><span>Ruby</span></label>
           <label class="option"><input type="checkbox" name="q2" value="cobol" /><span>COBOL</span></label>
           <label class="option"><input type="checkbox" name="q2" value="html" /><span>HTML</span></label>
         </div>
       </div>

       <div class="form-field">
         <div class="question-title">3. Which of these are compiled languages?</div>
         <div class="option-list">
           <label class="option"><input type="checkbox" name="q3" value="c" /><span>C</span></label>
           <label class="option"><input type="checkbox" name="q3" value="python" /><span>Python</span></label>
           <label class="option"><input type="checkbox" name="q3" value="rust" /><span>Rust</span></label>
           <label class="option"><input type="checkbox" name="q3" value="sql" /><span>SQL</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
         <div class="result" id="result" aria-live="polite"></div>
       </div>
     </form>
   </main>

   <script>
     const answers = {
       q1: ['python', 'javascript'],
       q2: ['javascript', 'ruby', 'html'],
       q3: ['c', 'rust']
     };

     const form = document.getElementById('quizForm');
     const result = document.getElementById('result');

     function getSelectedValues(name) {
       return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
     }

     function sameSet(a, b) {
       return a.length === b.length && a.every((value) => b.includes(value));
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const score = Object.keys(answers).reduce((total, key) => {
         const selected = getSelectedValues(key);
         return total + (sameSet(selected, answers[key]) ? 1 : 0);
       }, 0);

       result.textContent = `You scored ${score} out of 3.`;
     });
   </script>
 </body>
 </html>

')
